css:
@import url('https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600&display=swap');

:root {
    --primary-color: #FF6F61;  /* Red */
    --secondary-color: #D15C4A;  /* Darker Red */
    --accent-color: #FF6584;  /* Accent color stays the same */
    --dark-color: #2d3748;
    --light-color: #f7fafc;
    --border-color: #e2e8f0;
}

body {
    font-family: 'Poppins', Arial, sans-serif;
    font-size: 13px;
    margin: 0;
    padding: 20px;
    color: var(--dark-color);
    background-color: #f5f7fa;
    line-height: 1.5;
}

.invoice-container {
    max-width: 800px;
    margin: 0 auto;
    background: white;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
    border-radius: 8px;
    overflow: hidden;
    position: relative;
}

.invoice-header {
    background: white;  /* White background for header */
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);  /* Light shadow for the header */
    color: var(--primary-color);  /* Set text color to primary red */
    padding: 25px 30px;
    text-align: center;
    position: relative;
    border-bottom: 3px solid var(--primary-color);  /* Border for separation */
}

.invoice-header h2 {
    margin: 0;
    font-size: 24px;
    font-weight: 600;
    letter-spacing: 1px;
}

.company-name {
    font-size: 20px;
    font-weight: 500;
    margin-top: 5px;
    display: block;
}

.company-address {
    font-size: 12px;
    margin-top: 8px;
    opacity: 0.9;
}

.gstin-badge {
    display: inline-block;
    background: rgba(255, 255, 255, 0.2);
    padding: 5px 12px;
    border-radius: 20px;
    font-size: 11px;
    margin-top: 10px;
    font-weight: 500;
}

.invoice-body {
    padding: 25px 30px;
}

.details-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 25px;
}

.details-table th, 
.details-table td {
    padding: 10px 12px;
    border: 1px solid var(--border-color);
    text-align: left;
}

.details-table th {
    background-color: #f8fafc;
    font-weight: 500;
    color: var(--dark-color);
}

.billed-to-container {
    display: flex;
    gap: 20px;
    margin-bottom: 25px;
}

.billed-to-box {
    flex: 1;
    border: 1px solid var(--border-color);
    border-radius: 6px;
    padding: 15px;
    background: #f8fafc;
}

.billed-to-box h3 {
    margin: 0 0 10px 0;
    font-size: 14px;
    color: var(--primary-color);
    border-bottom: 1px dashed var(--border-color);
    padding-bottom: 8px;
}

.items-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 25px;
}

.items-table th {
    background: linear-gradient(to bottom, #f8fafc, #eef2f6);
    padding: 12px 10px;
    text-align: left;
    font-weight: 500;
    color: var(--dark-color);
    border: 1px solid var(--border-color);
}

.items-table td {
    padding: 10px;
    border: 1px solid var(--border-color);
    vertical-align: top;
}

.items-table tr:nth-child(even) {
    background-color: #f8fafc;
}

.highlight-row {
    background-color: rgba(255, 111, 97, 0.1) !important;
    font-weight: 500;
}

.total-section {
    background: #f8fafc;
    border-radius: 6px;
    padding: 15px;
    margin-top: 20px;
    border: 1px solid var(--border-color);
}

.total-row {
    display: flex;
    justify-content: space-between;
    margin-bottom: 8px;
}

.grand-total {
    font-size: 16px;
    font-weight: 600;
    color: var(--primary-color);
    border-top: 1px dashed var(--border-color);
    padding-top: 10px;
    margin-top: 10px;
}

.signature-section {
    margin-top: 40px;
    text-align: right;
}

.signature-line {
    display: inline-block;
    width: 200px;
    border-top: 1px solid var(--dark-color);
    margin-top: 60px;
}

.amount-in-words {
    background: #f8fafc;
    padding: 15px;
    border-radius: 6px;
    margin: 20px 0;
    font-style: italic;
    border: 1px solid var(--border-color);
}

.page-break {
    page-break-after: always;
    height: 0;
}

.text-right {
    text-align: right;
}

.text-center {
    text-align: center;
}

.text-bold {
    font-weight: 600;
}

.product-name {
    color: var(--secondary-color);
    font-weight: 500;
    margin-bottom: 50px;
}

.url-name {
    color: var(--secondary-color);
    font-weight: 500;
    font-size: 14px;
}
